// Replace the record with your own readings (from an MQTT-in node, a serial port, …).
const reading = {
  station: 'backyard-01',
  name: 'Back yard',
  lat: 21.3069,
  lon: -157.8103,
  time: new Date().toISOString(),
  temperature_c: global.get('temperature_c') ?? null,
};
msg.payload = {
  schema: 'oneview.ingest.v1',
  source: 'node-red-weather-stations',
  records: [reading],
};
msg.headers = {
  Authorization: 'Bearer ' + env.get('ONEVIEW_INGEST_TOKEN'),
  'Content-Type': 'application/json',
};
return msg;
